// ============================================================================
// 🌌 HyperSpacetimeConduit: 超維時空躍遷隧道 (Pro Generative Audio-Reactive Engine)
// 11 人專家架構設計：粒子流體雙核動力學 + 8大拓撲世界觀突變 + 全息光學後製
// ============================================================================

(function() {
  // ── 1. 8 大時空世界觀基因庫 (Cosmic Topology Archetypes) ──
  const ARCHETYPES = [
    {
      id: "QUANTUM_STRINGS",
      name: "量子弦網流體 (Quantum String Fluid)",
      baseHue: 175,
      palette: ["#00f0ff", "#00df89", "#052e3d", "#7cffd4", "#ffffff"],
      sides: 0, // 圓滑超流體
      vortexSpeed: 0.015,
      glowStyle: "cyan_stream",
      wireframe: false,
      particleRatio: [0.35, 0.45, 0.20],
      bgAlpha: 28
    },
    {
      id: "EVENT_HORIZON",
      name: "事件視界引力透鏡 (Event Horizon Lensing)",
      baseHue: 25,
      palette: ["#ff4500", "#ffaa00", "#1a0500", "#ff0055", "#ffe4b5"],
      sides: 0,
      vortexSpeed: 0.025,
      glowStyle: "accretion_fire",
      wireframe: false,
      particleRatio: [0.50, 0.35, 0.15],
      bgAlpha: 34
    },
    {
      id: "CYBER_TESSERACT",
      name: "超維賽博拓撲管道 (Cyber Hyper-Tesseract)",
      baseHue: 285,
      palette: ["#ff007f", "#00f5d4", "#120024", "#7b2cbf", "#ffffff"],
      sides: 6, // 六角晶格蜂巢
      vortexSpeed: 0.010,
      glowStyle: "neon_matrix",
      wireframe: true,
      particleRatio: [0.25, 0.55, 0.20],
      bgAlpha: 24
    },
    {
      id: "ABYSSAL_BIOLUM",
      name: "深海發光以太旋渦 (Abyssal Bioluminescent Vortex)",
      baseHue: 200,
      palette: ["#0d9488", "#38bdf8", "#021c24", "#818cf8", "#ccfbf1"],
      sides: 0,
      vortexSpeed: 0.008,
      glowStyle: "biolum_fog",
      wireframe: false,
      particleRatio: [0.40, 0.40, 0.20],
      bgAlpha: 20
    },
    {
      id: "NEBULA_PULSAR",
      name: "星雲吸積脈衝星管 (Nebula Accretion Pulsar)",
      baseHue: 250,
      palette: ["#8b5cf6", "#ec4899", "#110e2e", "#fbbf24", "#fdf4ff"],
      sides: 8, // 八邊星盤
      vortexSpeed: 0.030,
      glowStyle: "plasma_jet",
      wireframe: true,
      particleRatio: [0.30, 0.50, 0.20],
      bgAlpha: 30
    },
    {
      id: "BRUTALIST_CHASM",
      name: "粗野幾何石陣裂隙 (Brutalist Monolith Chasm)",
      baseHue: 40,
      palette: ["#d97706", "#78716c", "#1c1917", "#f59e0b", "#e7e5e4"],
      sides: 4, // 四方巨石裂隙
      vortexSpeed: 0.006,
      glowStyle: "amber_ember",
      wireframe: true,
      particleRatio: [0.20, 0.60, 0.20],
      bgAlpha: 40
    },
    {
      id: "PRISM_REFRACTION",
      name: "全息稜鏡光譜迴廊 (Prismatic Refraction Corridor)",
      baseHue: 320,
      palette: ["#f43f5e", "#06b6d4", "#10b981", "#a855f7", "#ffffff"],
      sides: 3, // 三稜鏡幾何
      vortexSpeed: 0.018,
      glowStyle: "spectral_rainbow",
      wireframe: true,
      particleRatio: [0.30, 0.50, 0.20],
      bgAlpha: 22
    },
    {
      id: "ZEN_INK_WORMHOLE",
      name: "水墨禪意虛空蟲洞 (Zen Ink Wash Wormhole)",
      baseHue: 45,
      palette: ["#171717", "#44403c", "#0a0a0a", "#d97706", "#f5f5f4"],
      sides: 0,
      vortexSpeed: 0.005,
      glowStyle: "zen_gold_mist",
      wireframe: false,
      particleRatio: [0.45, 0.35, 0.20],
      bgAlpha: 18
    }
  ];

  // ── 2. 全域狀態與對象池 ──
  let currentGenome = null;
  let particles = [];
  let shockRings = [];
  const TOTAL_PARTICLES = 1200;
  const RING_LAYERS = 32;
  const FOV = 480;
  const TUNNEL_DEPTH = 3200;

  let zProgress = 0;
  let cameraRoll = 0;
  let shakeX = 0, shakeY = 0;
  let lastBeatTime = 0;

  // ── 3. 基因隨機突變器 (Genome Mutator) ──
  function mutateGenome(archetypeIndex = null) {
    let archIdx = (archetypeIndex !== null && archetypeIndex >= 0 && archetypeIndex < ARCHETYPES.length)
      ? archetypeIndex
      : Math.floor(Math.random() * ARCHETYPES.length);

    let baseArch = ARCHETYPES[archIdx];

    // 多態隨機微調，確保每次實例化皆是孤本
    currentGenome = {
      archetype: baseArch,
      sides: baseArch.sides > 0 ? baseArch.sides : (Math.random() < 0.35 ? [3, 4, 5, 6, 8][Math.floor(Math.random() * 5)] : 0),
      radius: 220 + Math.random() * 120,
      twistPitch: (Math.random() < 0.5 ? 1 : -1) * (0.4 + Math.random() * 1.2),
      curveFreqX: 0.0012 + Math.random() * 0.0015,
      curveFreqY: 0.0009 + Math.random() * 0.0012,
      curveAmpX: 120 + Math.random() * 100,
      curveAmpY: 90 + Math.random() * 80,
      speedBase: 14 + Math.random() * 10,
      vortexRate: baseArch.vortexSpeed * (0.8 + Math.random() * 0.4),
      palette: [...baseArch.palette],
      glowIntensity: 0.7 + Math.random() * 0.5,
      wireframe: baseArch.wireframe || (Math.random() < 0.3)
    };

    // 重新初始化粒子對象池
    initParticles();
    console.log(`🌌 [HyperSpacetimeConduit] 基因突變成功: 【${currentGenome.archetype.name}】 多邊形邊數: ${currentGenome.sides === 0 ? '平滑圓管' : currentGenome.sides + ' 邊形'} 基礎半徑: ${currentGenome.radius.toFixed(0)}px`);
  }

  // ── 4. 粒子對象池初始化 (Object Pool) ──
  function initParticles() {
    particles = new Array(TOTAL_PARTICLES);
    const rLattice = currentGenome.archetype.particleRatio[0];
    const rStreak = currentGenome.archetype.particleRatio[1];

    for (let i = 0; i < TOTAL_PARTICLES; i++) {
      let type = "lattice";
      if (i > TOTAL_PARTICLES * (rLattice + rStreak)) {
        type = "core";
      } else if (i > TOTAL_PARTICLES * rLattice) {
        type = "streak";
      }

      particles[i] = {
        type: type,
        angle: Math.random() * Math.PI * 2,
        radOffset: (Math.random() - 0.5) * 80,
        z: Math.random() * TUNNEL_DEPTH,
        speedFactor: 0.6 + Math.random() * 0.9,
        size: type === "core" ? (1.5 + Math.random() * 3) : (type === "streak" ? (2 + Math.random() * 4) : (1.2 + Math.random() * 2.5)),
        colorIdx: Math.floor(Math.random() * currentGenome.palette.length),
        phase: Math.random() * Math.PI * 2,
        life: Math.random()
      };
    }
    shockRings = [];
  }

  // ── 5. p5.js setup 函式 ──
  window.setup = function() {
    createCanvas(windowWidth, windowHeight);
    noSmooth();
    mutateGenome();
  };

  // ── 6. 3D 空間樣條計算 (Spline Centerline) ──
  function getTunnelCenter(z, timeSec, midEnergy) {
    let t = timeSec * 0.8;
    let waveScale = 1.0 + (midEnergy || 0) * 1.5;
    let cx = Math.sin(z * currentGenome.curveFreqX + t) * currentGenome.curveAmpX * waveScale;
    let cy = Math.cos(z * currentGenome.curveFreqY + t * 0.7) * currentGenome.curveAmpY * waveScale;
    return { x: cx, y: cy };
  }

  // ── 7. p5.js draw 渲染主迴圈 ──
  window.draw = function() {
    // 取得音訊遙測特徵 (若無則使用預設值)
    let audioLow = (typeof window.audioLow !== 'undefined') ? window.audioLow : (typeof window.sub_bass !== 'undefined' ? window.sub_bass : 0.2);
    let audioMid = (typeof window.audioMid !== 'undefined') ? window.audioMid : 0.25;
    let audioHigh = (typeof window.audioHigh !== 'undefined') ? window.audioHigh : 0.2;
    let isBeat = Boolean(window.isBeat);
    let beatEnergy = (typeof window.beatEnergy !== 'undefined') ? window.beatEnergy : 0.0;
    let hihatDensity = (typeof window.hihatDensity !== 'undefined') ? window.hihatDensity : 0.1;
    let hihatTrig = Boolean(window.hihatTrigger);
    let chordColor = window.currentChordColor || null;
    let sectionName = window.sectionName || 'Verse';
    let stereoWidth = (typeof window.stereoWidth !== 'undefined') ? window.stereoWidth : 0.5;

    // 曲式導演自適應速度調製 (Section Director Modulation)
    let sectionSpeedMult = 1.0;
    let normSec = sectionName.toLowerCase();
    if (normSec.includes("intro") || normSec.includes("outro")) sectionSpeedMult = 0.45;
    else if (normSec.includes("build")) sectionSpeedMult = 2.2;
    else if (normSec.includes("drop") || normSec.includes("chorus")) sectionSpeedMult = 3.2;
    else if (normSec.includes("bridge")) sectionSpeedMult = 0.65;

    // 躍遷穿越瞬時速度計算 (Sub-Bass 衝擊加速)
    let warpBoost = 1.0 + audioLow * 3.2 + beatEnergy * 1.5;
    let currentSpeed = currentGenome.speedBase * sectionSpeedMult * warpBoost;
    zProgress += currentSpeed;

    // 攝影機微震顫與自轉
    if (isBeat && beatEnergy > 0.45) {
      shakeX = (Math.random() - 0.5) * 14 * beatEnergy;
      shakeY = (Math.random() - 0.5) * 14 * beatEnergy;
      // 觸發向前的震波衝擊環
      if (shockRings.length < 8) {
        shockRings.push({ z: TUNNEL_DEPTH * 0.95, speed: currentSpeed * 1.8, intensity: beatEnergy, maxR: currentGenome.radius * 2.2 });
      }
    } else {
      shakeX *= 0.85;
      shakeY *= 0.85;
    }
    cameraRoll += (0.004 + audioMid * 0.015) * currentGenome.twistPitch;

    // 繪製微透明背景以形成動態光跡 (Motion Trail Feedback)
    let bgAlpha = currentGenome.archetype.bgAlpha;
    if (normSec.includes("drop")) bgAlpha = Math.max(14, bgAlpha - 8); // Drop 段落延長光跡
    background(5, 5, 8, bgAlpha);

    let halfW = width * 0.5;
    let halfH = height * 0.5;
    let timeSec = millis() * 0.001;

    push();
    translate(halfW + shakeX, halfH + shakeY);
    rotate(cameraRoll);

    // ── 7.1 繪製隧道骨架幾何環 (Conduit Structural Rings) ──
    noFill();
    let dynamicRadius = currentGenome.radius * (1.0 + audioLow * 0.35);
    let sides = currentGenome.sides;
    let strokeW = 1.2 + audioHigh * 1.8;
    strokeWeight(strokeW);

    for (let r = 0; r < RING_LAYERS; r++) {
      let ringZ = (r * (TUNNEL_DEPTH / RING_LAYERS) - (zProgress % (TUNNEL_DEPTH / RING_LAYERS)) + TUNNEL_DEPTH) % TUNNEL_DEPTH;
      if (ringZ < 40) continue; // 避免除零或穿模

      let pScale = FOV / (ringZ + 1e-5);
      let centerOffset = getTunnelCenter(ringZ, timeSec, audioMid);
      let ringX = centerOffset.x * pScale;
      let ringY = centerOffset.y * pScale;
      let rRadius = dynamicRadius * pScale;
      let rAspect = 1.0 + (stereoWidth - 0.5) * 0.4; // 聲場寬度控制隧道橫向扁平度

      // 深度暗角漸變 (Volumetric Depth Fog)
      let depthFade = map(ringZ, 40, TUNNEL_DEPTH, 255, 12);
      let palColor = currentGenome.palette[r % currentGenome.palette.length];
      let strokeCol = color(palColor);
      strokeCol.setAlpha(depthFade * currentGenome.glowIntensity);
      stroke(strokeCol);

      push();
      translate(ringX, ringY);
      rotate(ringZ * 0.0008 * currentGenome.twistPitch + timeSec * currentGenome.vortexRate);

      if (sides <= 0) {
        // 平滑圓形管道
        ellipse(0, 0, rRadius * 2 * rAspect, rRadius * 2);
      } else {
        // 多邊形幾何環 (三稜/四方/六角/八邊)
        beginShape();
        for (let s = 0; s < sides; s++) {
          let a = (s / sides) * Math.PI * 2;
          let vx = Math.cos(a) * rRadius * rAspect;
          let vy = Math.sin(a) * rRadius;
          vertex(vx, vy);
        }
        endShape(CLOSE);
      }

      // 骨架網格縱向連接線 (Wireframe Lattice)
      if (currentGenome.wireframe && r % 4 === 0 && r < RING_LAYERS - 1) {
        let nextZ = ringZ + (TUNNEL_DEPTH / RING_LAYERS);
        let nextScale = FOV / (nextZ + 1e-5);
        let nextCenter = getTunnelCenter(nextZ, timeSec, audioMid);
        let nextRadius = dynamicRadius * nextScale;
        strokeWeight(0.7);
        for (let s = 0; s < (sides > 0 ? sides : 6); s++) {
          let a = (s / (sides > 0 ? sides : 6)) * Math.PI * 2;
          let x1 = Math.cos(a) * rRadius * rAspect;
          let y1 = Math.sin(a) * rRadius;
          let x2 = (nextCenter.x * nextScale - ringX) + Math.cos(a) * nextRadius * rAspect;
          let y2 = (nextCenter.y * nextScale - ringY) + Math.sin(a) * nextRadius;
          line(x1, y1, x2, y2);
        }
        strokeWeight(strokeW);
      }
      pop();
    }

    // ── 7.2 渲染震波衝擊環 (Shockwave Rings) ──
    for (let si = shockRings.length - 1; si >= 0; si--) {
      let sRing = shockRings[si];
      sRing.z -= sRing.speed;
      if (sRing.z <= 30) {
        shockRings.splice(si, 1);
        continue;
      }
      let sScale = FOV / (sRing.z + 1e-5);
      let sCenter = getTunnelCenter(sRing.z, timeSec, audioMid);
      let sR = sRing.maxR * sScale * (1.0 + (TUNNEL_DEPTH - sRing.z) / TUNNEL_DEPTH);
      let sAlpha = map(sRing.z, 30, TUNNEL_DEPTH, 255, 0) * sRing.intensity;
      stroke(255, 255, 255, sAlpha);
      strokeWeight(2.5 * sScale);
      noFill();
      ellipse(sCenter.x * sScale, sCenter.y * sScale, sR * 2, sR * 2);
    }

    // ── 7.3 粒子系統渲染 (Particle Flow & Warp Streaks) ──
    noStroke();
    let vortexAngleOffset = timeSec * currentGenome.vortexRate;

    for (let i = 0; i < TOTAL_PARTICLES; i++) {
      let p = particles[i];
      p.z -= currentSpeed * p.speedFactor;

      // 循環復用粒子 (Pool Recycle)
      if (p.z <= 25) {
        p.z += TUNNEL_DEPTH;
        p.angle = Math.random() * Math.PI * 2;
        p.colorIdx = Math.floor(Math.random() * currentGenome.palette.length);
      }

      let pZ = p.z;
      let pScale = FOV / (pZ + 1e-5);
      let cCenter = getTunnelCenter(pZ, timeSec, audioMid);

      // 角速度渦流旋轉
      let curAngle = p.angle + (TUNNEL_DEPTH - pZ) * 0.0012 * currentGenome.twistPitch + vortexAngleOffset;
      let curRad = (p.type === "core")
        ? (p.radOffset * 0.4 * (1.0 + audioHigh * 2.0))
        : (dynamicRadius + p.radOffset);

      let px = cCenter.x * pScale + Math.cos(curAngle) * curRad * pScale;
      let py = cCenter.y * pScale + Math.sin(curAngle) * curRad * pScale;

      let pAlpha = map(pZ, 25, TUNNEL_DEPTH, 255, 10);
      let pSize = p.size * pScale * (1.0 + (hihatTrig ? 1.2 : 0.0));

      let pColHex = currentGenome.palette[p.colorIdx];
      let pCol = color(pColHex);
      pCol.setAlpha(pAlpha);
      fill(pCol);

      if (p.type === "streak" && pZ < 1200) {
        // 高速近景拉絲流光 (Warp Streaks)
        let streakLen = map(currentSpeed, 10, 80, 8, 45) * pScale;
        let prevZ = pZ + currentSpeed * 1.5;
        let prevScale = FOV / (prevZ + 1e-5);
        let prevCenter = getTunnelCenter(prevZ, timeSec, audioMid);
        let pxPrev = prevCenter.x * prevScale + Math.cos(curAngle) * curRad * prevScale;
        let pyPrev = prevCenter.y * prevScale + Math.sin(curAngle) * curRad * prevScale;

        stroke(pCol);
        strokeWeight(Math.max(1.0, pSize * 0.8));
        line(px, py, pxPrev, pyPrev);
        noStroke();
      } else {
        circle(px, py, Math.max(1.0, pSize));
      }
    }

    // ── 7.4 中心奇異點光暈 (Singularity Anamorphic Glow) ──
    let coreCenter = getTunnelCenter(TUNNEL_DEPTH * 0.95, timeSec, audioMid);
    let coreScale = FOV / (TUNNEL_DEPTH * 0.95);
    let cx = coreCenter.x * coreScale;
    let cy = coreCenter.y * coreScale;

    // 奇異點核心發光球
    let coreSize = (35 + audioLow * 60 + beatEnergy * 40);
    let coreCol = color(chordColor || currentGenome.palette[0]);
    coreCol.setAlpha(120);
    fill(coreCol);
    noStroke();
    circle(cx, cy, coreSize);

    // 變形寬銀幕光暈 (Anamorphic Streak Lens Flare)
    let streakWidth = width * (0.35 + audioLow * 0.5);
    let streakCol = color(currentGenome.palette[1]);
    streakCol.setAlpha(65 + audioLow * 120);
    fill(streakCol);
    ellipse(cx, cy, streakWidth, 3.5 + audioLow * 5.0);

    // ── 7.5 重拍色散仿真 (Chromatic Aberration Ghosting on Beat) ──
    if (isBeat && beatEnergy > 0.5) {
      let ghostShift = (beatEnergy * 8);
      stroke(255, 0, 100, 70);
      strokeWeight(1.5);
      noFill();
      ellipse(cx - ghostShift, cy, coreSize * 1.6, coreSize * 1.6);
      stroke(0, 240, 255, 70);
      ellipse(cx + ghostShift, cy, coreSize * 1.6, coreSize * 1.6);
    }

    pop();

    // ── 7.6 邊緣動態暗角 (Cinematic Vignette) ──
    // 使用簡單高效徑向明暗壓低邊緣
    noFill();
    stroke(0, 0, 0, 90 + audioLow * 40);
    strokeWeight(width * 0.08);
    rect(0, 0, width, height);
  };

  // ── 8. 視窗尺寸自適應與公開接口 ──
  window.windowResized = function() {
    resizeCanvas(windowWidth, windowHeight);
  };

  // 支援滑鼠點擊或外部指令即刻觸發新世界觀突變
  window.mousePressed = function() {
    mutateGenome();
  };

  window.mutateSpacetimeConduit = function(archetypeIndex = null) {
    mutateGenome(archetypeIndex);
  };

  window.getSpacetimeGenome = function() {
    return currentGenome;
  };

})();

